#include <stdio.h>
#include <stdlib.h>

int main(void) {
    size_t count = 10;
    int *numbers = malloc(count * sizeof(*numbers));
    if (numbers == NULL) {
        fprintf(stderr, "فشل تخصيص الذاكرة!\n");
        return 1;
    }

    for (size_t i = 0; i < count; i++) {
        numbers[i] = (int)(i * 10);
    }

    free(numbers); // تحرير الذاكرة لمنع التسرب
    numbers = NULL;
    return 0;
}

char *buffer = malloc(256);
if (buffer != NULL) {
    // استخدام الذاكرة...
    free(buffer);
    buffer = NULL; // حماية من Use-After-Free
}

int *scores = calloc(50, sizeof(*scores));
if (!scores) return -1;
// scores[0] حتى scores[49] كلها 0 بأمان
free(scores);
scores = NULL;

int *arr = malloc(5 * sizeof(int));
// نريد زيادة الحجم إلى 10
int *temp = realloc(arr, 10 * sizeof(int));
if (temp == NULL) {
    // معالجة الفشل مع الاحتفاظ بالمؤشر الأصلي arr آمناً
    free(arr);
    return 1;
}
arr = temp; // نجحت العملية
free(arr);

